<?php
namespace App\Modules\Orders\Domain\Models;
use App\Models\User;use App\Modules\Orders\Domain\Enums\OrderPriority;use App\Modules\Orders\Domain\Enums\SalesOrderStatus;use App\Modules\People\Domain\Models\Person;use App\Modules\Pricing\Domain\Models\PriceList;use Illuminate\Database\Eloquent\Attributes\Fillable;use Illuminate\Database\Eloquent\Concerns\HasUlids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;
#[Fillable(['document_number','customer_person_id','ordered_at','due_at','priority','status','price_list_id','subtotal','discount','total','advance_amount','balance_amount','notes','created_by'])]
class SalesOrder extends Model { use HasUlids; public function customer():BelongsTo{return $this->belongsTo(Person::class,'customer_person_id');}public function priceList():BelongsTo{return $this->belongsTo(PriceList::class);}public function creator():BelongsTo{return $this->belongsTo(User::class,'created_by');}public function lines():HasMany{return $this->hasMany(SalesOrderLine::class);}public function histories():HasMany{return $this->hasMany(OrderStatusHistory::class);}protected function casts():array{return ['ordered_at'=>'datetime','due_at'=>'datetime','priority'=>OrderPriority::class,'status'=>SalesOrderStatus::class,'subtotal'=>'integer','discount'=>'integer','total'=>'integer','advance_amount'=>'integer','balance_amount'=>'integer'];} }
